using System;\nusing System.Collections.Generic;\nusing System.Threading.Tasks;\nusing System.Numerics;\n\nnamespace MagnumOpus.Core\n{\n    public enum TransactionStatus { Pending, Confirmed, Failed }\n\n    public record Transaction\n    {\n        public Guid Id { get; init; } = Guid.NewGuid();\n        public string From { get; init; } = string.Empty;\n        public string To { get; init; } = string.Empty;\n        public decimal Amount { get; init; }\n        public string Symbol { get; init; } = \"ETH\";\n        public DateTime Timestamp { get; init; } = DateTime.UtcNow;\n        public TransactionStatus Status { get; set; } = TransactionStatus.Pending;\n        public string TxHash { get; set; } = string.Empty;\n    }\n\n    public interface ITransactionProcessor\n    {\n        Task<Transaction> SubmitAsync(string from, string to, decimal amount, string symbol = \"ETH\");\n        Task<Transaction> GetAsync(Guid id);\n        Task<IReadOnlyCollection<Transaction>> ListAsync(int limit = 100);\n    }\n\n    public class MockTransactionProcessor : ITransactionProcessor\n    {\n        private readonly Dictionary<Guid, Transaction> _store = new();\n        private readonly Random _rnd = new();\n\n        public async Task<Transaction> SubmitAsync(string from, string to, decimal amount, string symbol = \"ETH\")\n        {\n            if (string.IsNullOrWhiteSpace(from) || string.IsNullOrWhiteSpace(to))\n                throw new ArgumentException(\"From and To addresses must be provided.\");\n\n            var tx = new Transaction\n            {\n                From = from,\n                To = to,\n                Amount = amount,\n                Symbol = symbol\n            };\n\n            _store[tx.Id] = tx;\n\n            // Simulate async network latency\n            await Task.Delay(_rnd.Next(200, 800));\n\n            // Mock hash generation\n            tx.TxHash = GenerateMockHash(tx);\n            tx.Status = TransactionStatus.Confirmed;\n\n            return tx;\n        }\n\n        public Task<Transaction> GetAsync(Guid id)\n        {\n            if (_store.TryGetValue(id, out var tx))\n                return Task.FromResult(tx);\n            throw new KeyNotFoundException($\"Transaction {id} not found.\");\n        }\n\n        public Task<IReadOnlyCollection<Transaction>> ListAsync(int limit = 100)\n        {\n            var list = new List<Transaction>(_store.Values);\n            list.Sort((a, b) => b.Timestamp.CompareTo(a.Timestamp));\n            if (limit > 0 && limit < list.Count)\n                list = list.GetRange(0, limit);\n            return Task.FromResult((IReadOnlyCollection<Transaction>)list);\n        }\n\n        private static string GenerateMockHash(Transaction tx)\n        {\n            // Simple deterministic mock hash using SHA256 from System.Security.Cryptography\n            using var sha = System.Security.Cryptography.SHA256.Create();\n            var payload = $\"{tx.Id}{tx.From}{tx.To}{tx.Amount}{tx.Symbol}{tx.Timestamp:o}\";\n            var bytes = sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(payload));\n            return \"0x\" + BitConverter.ToString(bytes).Replace(\"-\", \"\").ToLowerInvariant();\n        }\n    }\n}\n